mapper.select:
SELECT m.user_id AS userId, m.name AS name, m.email AS email, m.role AS role, m.subscribe AS subscribe, m.ai_count AS aiCount, m.created_at AS createdAt, m.deleted AS deleted, m.withdrawn_at AS withdrawnAt, m.login_restriction_days AS loginRestrictionDays, m.login_restricted_at AS loginRestrictedAt, m.login_restricted_until AS loginRestrictedUntil, m.login_restriction_reason AS loginRestrictionReason, m.login_restricted_by AS loginRestrictedBy, ( SELECT COUNT(*) FROM report r WHERE r.reported_user_id = m.user_id ) AS reportReceivedCount, AS status FROM member m
AND ( m.user_id LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%') OR m.email LIKE CONCAT('%', #{keyword}, '%') )
AND m.role = #{role}
AND m.subscribe = #{subscribe}
AND m.deleted = 1 AND COALESCE(m.login_restriction_days, 0) = 0
AND m.deleted = 1 AND COALESCE(m.login_restriction_days, 0) > 0 AND ( m.login_restricted_until IS NULL OR m.login_restricted_until > NOW() )
AND m.deleted != 1
ORDER BY m.created_at DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE member
SET subscribe = #{subscribe}
WHERE user_id = #{userId}
  AND deleted = 1
